p='src/server/repositories/organization-repository.ts'
s=open(p).read()
s=s.replace('import { and, eq, isNull, like } from "drizzle-orm";','import { and, eq, gt, isNull, like } from "drizzle-orm";\nimport { ORG_SLUG_HOLD_DAYS } from "@/config/constants";')
s=s.replace('import { getDb, members, organizations } from "@/server/db";','import { getDb, members, organizations, retiredOrgSlugs } from "@/server/db";')
s=s.replace('''export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}''','''/** Retirements whose hold has not yet ended are retired at or after this instant (exclusive). */
function holdCutoff(now: Date = new Date()): string {
  return toIsoTimestamp(
    new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000),
  );
}

/**
 * Resolves a slug to a live org: its current slug, or a slug it retired less
 * than `ORG_SLUG_HOLD_DAYS` ago (ADR 0005). Every slug lookup goes through here.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const held = await findHeldRetiredSlug(slug);
  if (!held) return null;

  const owner = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.id, held.orgId), isNull(organizations.archivedAt)))
    .get();
  return owner ? toOrganization(owner) : null;
}

/** The retirement record for `slug` if its hold is still running. */
export async function findHeldRetiredSlug(
  slug: string,
): Promise<{ readonly slug: string; readonly orgId: OrgId } | null> {
  const row = getDb()
    .select()
    .from(retiredOrgSlugs)
    .where(
      and(eq(retiredOrgSlugs.slug, slug), gt(retiredOrgSlugs.retiredAt, holdCutoff())),
    )
    .get();
  return row ? { slug: row.slug, orgId: row.orgId as OrgId } : null;
}

/** Any org (live or archived) whose current slug is `slug`. */
export async function findOrgHoldingCurrentSlug(
  slug: string,
): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Moves the org to `newSlug`, retiring `oldSlug` from now. Any retirement
 * record for `newSlug` (the org's own, or an expired one) is cleared.
 */
export async function changeOrgSlug(
  orgId: OrgId,
  oldSlug: string,
  newSlug: string,
): Promise<Organization> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());

  return db.transaction((tx) => {
    tx.delete(retiredOrgSlugs).where(eq(retiredOrgSlugs.slug, newSlug)).run();
    tx.delete(retiredOrgSlugs).where(eq(retiredOrgSlugs.slug, oldSlug)).run();
    tx.insert(retiredOrgSlugs)
      .values({ slug: oldSlug, orgId, retiredAt: stamp })
      .run();
    const row = tx
      .update(organizations)
      .set({ slug: newSlug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
    if (!row) throw new Error(`Organization ${orgId} not found`);
    return toOrganization(row);
  });
}''')
s=s.replace('''    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);''','''    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const held = getDb()
    .select({ slug: retiredOrgSlugs.slug })
    .from(retiredOrgSlugs)
    .where(
      and(
        like(retiredOrgSlugs.slug, `${prefix}%`),
        gt(retiredOrgSlugs.retiredAt, holdCutoff()),
      ),
    )
    .all();
  return [...rows, ...held].map((row) => row.slug);''')
open(p,'w').write(s)

