''')
s=s.replace('''/**
 * Deletion is a soft''','''/**
 * Changes the workspace URL (ADR 0005): the exact slug typed, refused when
 * unavailable, the old slug retired for `ORG_SLUG_HOLD_DAYS`.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) return org;

  assertValidSlug(input.slug);

  const holder = await orgRepo.findOrgHoldingCurrentSlug(input.slug);
  if (holder && holder.id !== org.id) {
    throw new InvalidSlugError(input.slug, "is not available");
  }
  const held = await orgRepo.findHeldRetiredSlug(input.slug);
  if (held && held.orgId !== org.id) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const updated = await orgRepo.changeOrgSlug(org.id, org.slug, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: org.slug,
    to: updated.slug,
  });

  return updated;
}

/**
 * Deletion is a soft''')
open(p,'w').write(s)
